package com.onlyflips;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Talks to the OnlyFlips backend to learn whether the account is Pro and, if so, fetch Smart Picks.
 * The lock is real: Smart Picks data only comes back from the server for Pro accounts.
 */
@Slf4j
@Singleton
public class OnlyFlipsAccount
{
	public static class Pick
	{
		public int itemId;
		public String name;
		public long margin;
		public int volume;
		public boolean owned;
	}

	@Inject
	private OkHttpClient http;

	@Inject
	private Gson gson;

	@Inject
	private OnlyFlipsConfig config;

	private volatile boolean pro = false;
	private volatile boolean known = false;
	private volatile List<Pick> picks = Collections.emptyList();

	private String base()
	{
		String e = config.endpoint() == null ? "" : config.endpoint().trim();
		return e.replaceAll("/flip/?$", "");
	}

	public void refresh()
	{
		final String token = config.token() == null ? "" : config.token().trim();
		if (token.isEmpty())
		{
			pro = false;
			known = false;
			picks = Collections.emptyList();
			return;
		}

		// Who am I / am I Pro?
		try
		{
			Request req = new Request.Builder().url(base() + "/me").header("Authorization", "Bearer " + token).build();
			try (Response r = http.newCall(req).execute())
			{
				if (r.isSuccessful() && r.body() != null)
				{
					JsonObject o = gson.fromJson(r.body().charStream(), JsonObject.class);
					pro = o != null && o.has("pro") && o.get("pro").getAsBoolean();
					known = true;
				}
				else
				{
					known = false;
				}
			}
		}
		catch (Exception ex)
		{
			known = false;
			log.warn("OnlyFlips /me failed", ex);
		}

		// Smart Picks (server enforces Pro; returns 402 otherwise)
		if (pro)
		{
			try
			{
				Request req = new Request.Builder().url(base() + "/smart-picks").header("Authorization", "Bearer " + token).build();
				try (Response r = http.newCall(req).execute())
				{
					if (r.isSuccessful() && r.body() != null)
					{
						JsonObject o = gson.fromJson(r.body().charStream(), JsonObject.class);
						List<Pick> list = new ArrayList<>();
						if (o != null && o.has("picks") && o.get("picks").isJsonArray())
						{
							for (JsonElement el : o.getAsJsonArray("picks"))
							{
								try
								{
									JsonObject p = el.getAsJsonObject();
									Pick pk = new Pick();
									pk.itemId = p.get("item_id").getAsInt();
									pk.name = p.get("item_name").getAsString();
									pk.margin = p.get("margin").getAsLong();
									pk.volume = p.has("volume") ? p.get("volume").getAsInt() : 0;
									pk.owned = p.has("owned") && p.get("owned").getAsBoolean();
									list.add(pk);
								}
								catch (Exception ignored)
								{
								}
							}
						}
						picks = list;
					}
				}
			}
			catch (Exception ex)
			{
				log.warn("OnlyFlips /smart-picks failed", ex);
			}
		}
		else
		{
			picks = Collections.emptyList();
		}
	}

	public boolean isPro()
	{
		return pro;
	}

	public boolean known()
	{
		return known;
	}

	public List<Pick> picks()
	{
		return picks;
	}
}

