package com.onlyflips;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Draws live margin (after tax) and a per-trade timer on items at the Grand Exchange.
 */
public class OnlyFlipsGeOverlay extends WidgetItemOverlay
{
	private static final int GRAND_EXCHANGE_GROUP_ID = 465; // GE interface

	private static final Color GREEN = new Color(0x57, 0xE0, 0x8A);
	private static final Color RED = new Color(0xFF, 0x6F, 0x6F);
	private static final Color YELLOW = new Color(0xFF, 0xCE, 0x4A);

	private final Client client;
	private final OnlyFlipsPriceService prices;
	private final OnlyFlipsOffers offers;
	private final OnlyFlipsConfig config;

	@Inject
	OnlyFlipsGeOverlay(Client client, OnlyFlipsPriceService prices, OnlyFlipsOffers offers, OnlyFlipsConfig config)
	{
		this.client = client;
		this.prices = prices;
		this.offers = offers;
		this.config = config;
		showOnInterfaces(GRAND_EXCHANGE_GROUP_ID);
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem item)
	{
		final Rectangle b = item.getCanvasBounds();
		if (b == null)
		{
			return;
		}
		g.setFont(FontManager.getRunescapeSmallFont());

		// Margin (after tax), drawn along the bottom of the icon
		if (config.showMargins())
		{
			final int[] p = prices.get(itemId);
			if (p != null && p[0] > 0 && p[1] > 0)
			{
				final long tax = OnlyFlipsPlugin.geTax(p[1], itemId);
				final long margin = p[1] - p[0] - tax;
				drawText(g, OnlyFlipsPlugin.shortGp(margin), b.x + 1, b.y + b.height - 1, margin >= 0 ? GREEN : RED);
			}
		}

		// Trade timer, drawn along the top of the icon
		if (config.showTimers())
		{
			final Long start = startForItem(itemId);
			if (start != null)
			{
				final long elapsed = System.currentTimeMillis() - start;
				final long mins = elapsed / 60000L;
				final Color c = mins < 10 ? GREEN : (mins < 15 ? YELLOW : RED);
				drawText(g, fmtTime(elapsed), b.x + 1, b.y + 10, c);
			}
		}
	}

	private Long startForItem(int itemId)
	{
		final GrandExchangeOffer[] all = client.getGrandExchangeOffers();
		if (all == null)
		{
			return null;
		}
		for (int i = 0; i < all.length; i++)
		{
			final GrandExchangeOffer o = all[i];
			if (o == null || o.getItemId() != itemId)
			{
				continue;
			}
			final GrandExchangeOfferState s = o.getState();
			if (s == GrandExchangeOfferState.BUYING || s == GrandExchangeOfferState.SELLING)
			{
				final long st = offers.startForSlot(i);
				if (st > 0)
				{
					return st;
				}
			}
		}
		return null;
	}

	private static String fmtTime(long ms)
	{
		long s = ms / 1000L;
		final long m = s / 60L;
		s = s % 60L;
		return m + ":" + (s < 10 ? "0" : "") + s;
	}

	private void drawText(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.onlyflips;

import java.util.Arrays;
import javax.inject.Singleton;

/**
 * Tracks when each GE offer slot became active, so the overlay can show a trade timer.
 */
@Singleton
public class OnlyFlipsOffers
{
	private final long[] start = new long[8];

	/** Called on every offer state change. active = the offer is currently buying/selling. */
	public void onState(int slot, boolean active)
	{
		if (slot < 0 || slot >= start.length)
		{
			return;
		}
		if (active)
		{
			if (start[slot] == 0)
			{
				start[slot] = System.currentTimeMillis();
			}
		}
		else
		{
			start[slot] = 0;
		}
	}

	/** @return epoch millis the offer in this slot started, or 0 if none. */
	public long startForSlot(int slot)
	{
		return (slot >= 0 && slot < start.length) ? start[slot] : 0;
	}

	public void reset()
	{
		Arrays.fill(start, 0);
	}
}

package com.onlyflips;

import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.io.IOException;
import java.time.temporal.ChronoUnit;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@PluginDescriptor(
	name = "OnlyFlips",
	description = "Auto-logs your Grand Exchange flips to your OnlyFlips account, with live GE margins and trade timers",
	tags = {"ge", "grand", "exchange", "flip", "flipping", "money", "merch", "onlyflips"}
)
public class OnlyFlipsPlugin extends Plugin
{
	private static final MediaType JSON = MediaType.parse("application/json");

	// Items exempt from the 2% GE tax (Old school bond + tools)
	private static final Set<Integer> TAX_EXEMPT = new HashSet<>(Arrays.asList(
		13190, 1755, 5325, 11090, 2347, 1733, 233, 5341, 8794, 5329, 5343, 1735, 952, 5331));
	private static final int BOND_ID = 13190;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private OnlyFlipsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OnlyFlipsGeOverlay geOverlay;

	@Inject
	private OnlyFlipsTopOverlay topOverlay;

	@Inject
	private OnlyFlipsSessionOverlay sessionOverlay;

	@Inject
	private OnlyFlipsSession session;

	@Inject
	private OnlyFlipsSmartOverlay smartOverlay;

	@Inject
	private OnlyFlipsAccount account;

	@Inject
	private OnlyFlipsPriceService priceService;

	@Inject
	private OnlyFlipsOffers offers;

	@Inject
	private ScheduledExecutorService executor;

	// Per-slot signature of the last completion we logged, so we don't double-send
	private final String[] lastSig = new String[8];

	// GE offer events are replayed right after login; ignore them until this time
	private long enableAfter = 0L;

	@Override
	protected void startUp()
	{
		Arrays.fill(lastSig, null);
		overlayManager.add(geOverlay);
		overlayManager.add(topOverlay);
		overlayManager.add(sessionOverlay);
		overlayManager.add(smartOverlay);
		executor.execute(() -> { account.refresh(); priceService.refresh(); });
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(geOverlay);
		overlayManager.remove(topOverlay);
		overlayManager.remove(sessionOverlay);
		overlayManager.remove(smartOverlay);
		offers.reset();
		Arrays.fill(lastSig, null);
	}

	@Schedule(period = 15, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void refreshPrices()
	{
		priceService.refreshLatest();
	}

	@Schedule(period = 180, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void refreshVolume()
	{
		priceService.refreshVolume();
	}

	@Schedule(period = 120, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void refreshAccount()
	{
		account.refresh();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			// Suppress the batch of offer events RuneLite replays right after login
			enableAfter = System.currentTimeMillis() + 4000L;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if ("onlyflips".equals(e.getGroup()))
		{
			executor.execute(() -> { account.refresh(); priceService.computeTop(); });
		}
	}

	@Subscribe
	public void onOverlayMenuClicked(OverlayMenuClicked e)
	{
		if (e.getOverlay() == sessionOverlay && OnlyFlipsSessionOverlay.RESET.equals(e.getEntry().getOption()))
		{
			session.reset();
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		final int slot = event.getSlot();
		final GrandExchangeOffer offer = event.getOffer();
		if (slot < 0 || slot >= lastSig.length || offer == null)
		{
			return;
		}

		final GrandExchangeOfferState state = offer.getState();

		// Trade-timer tracking (independent of logging)
		final boolean active = state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.SELLING;
		offers.onState(slot, active);

		if (state == GrandExchangeOfferState.EMPTY)
		{
			lastSig[slot] = null;
			return;
		}

		final int qty = offer.getQuantitySold();
		if (qty <= 0)
		{
			return; // nothing has transacted yet
		}

		final boolean isBuy = state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.CANCELLED_BUY;
		final boolean isSell = state == GrandExchangeOfferState.SOLD || state == GrandExchangeOfferState.CANCELLED_SELL;
		if (!isBuy && !isSell)
		{
			return; // still buying/selling, not a completed/cancelled result
		}

		// Skip the login replay window
		if (System.currentTimeMillis() < enableAfter)
		{
			return;
		}

		final long spent = offer.getSpent();
		final long pricePer = qty > 0 ? Math.round((double) spent / qty) : offer.getPrice();

		final String sig = state + ":" + offer.getItemId() + ":" + qty + ":" + spent;
		if (sig.equals(lastSig[slot]))
		{
			return; // duplicate event
		}
		lastSig[slot] = sig;

		final int itemId = offer.getItemId();

		// Session stats
		if (isBuy)
		{
			session.onBuy(spent);
		}
		else
		{
			session.onSell(spent, geTax(pricePer, itemId) * qty);
		}

		final String name = itemManager.getItemComposition(itemId).getName();

		send(isBuy ? "buy" : "sell", itemId, name, qty, pricePer);
	}

	private void send(String eventType, int itemId, String name, int qty, long pricePer)
	{
		final String token = config.token() == null ? "" : config.token().trim();
		if (token.isEmpty())
		{
			return;
		}
		final String url = config.endpoint() == null ? "" : config.endpoint().trim();
		if (url.isEmpty())
		{
			return;
		}

		final JsonObject body = new JsonObject();
		body.addProperty("event", eventType);
		body.addProperty("item_id", itemId);
		body.addProperty("item_name", name);
		body.addProperty("quantity", qty);
		body.addProperty("price", pricePer);

		final Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, body.toString()))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException ex)
			{
				log.warn("OnlyFlips sync failed", ex);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						if (config.chatNotify())
						{
							clientThread.invokeLater(() ->
								client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
									"[OnlyFlips] Synced " + eventType + " " + qty + " x " + name + " @ " + pricePer + " gp", null));
						}
					}
					else
					{
						log.warn("OnlyFlips sync HTTP {}", r.code());
					}
				}
			}
		});
	}

	/** GE sale tax: 2%, capped at 5m/item, none under 50 gp; bond = 10% conversion; tools exempt. */
	public static long geTax(long price, int itemId)
	{
		if (price < 50)
		{
			return 0;
		}
		if (itemId == BOND_ID)
		{
			return (long) Math.floor(price * 0.10);
		}
		if (TAX_EXEMPT.contains(itemId))
		{
			return 0;
		}
		return Math.min((long) Math.floor(price * 0.02), 5_000_000L);
	}

	public static String shortGp(long n)
	{
		final long a = Math.abs(n);
		if (a >= 1_000_000_000L)
		{
			return String.format("%.2fb", n / 1e9);
		}
		if (a >= 1_000_000L)
		{
			return String.format("%.2fm", n / 1e6);
		}
		if (a >= 1_000L)
		{
			return String.format("%.1fk", n / 1e3);
		}
		return Long.toString(n);
	}

	@Provides
	OnlyFlipsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OnlyFlipsConfig.class);
	}
}

package com.onlyflips;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Caches OSRS Wiki live prices + hourly volume, and computes the top recommended flips.
 */
@Slf4j
@Singleton
public class OnlyFlipsPriceService
{
	private static final String LATEST = "https://prices.runescape.wiki/api/v1/osrs/latest";
	private static final String HOURLY = "https://prices.runescape.wiki/api/v1/osrs/1h";
	private static final String UA = "OnlyFlips RuneLite plugin - runeledger.net";

	@Inject
	private OkHttpClient http;

	@Inject
	private Gson gson;

	@Inject
	private OnlyFlipsConfig config;

	@Inject
	private OnlyFlipsAccount account;

	// itemId -> [low (insta-sell), high (insta-buy)]
	private volatile Map<Integer, int[]> prices = Collections.emptyMap();
	// itemId -> 1h volume
	private volatile Map<Integer, Integer> volumes = Collections.emptyMap();
	// recommended flips, each [itemId, margin, volume], best first
	private volatile List<int[]> topFlips = Collections.emptyList();

	/** Full refresh — used on startup. */
	public void refresh()
	{
		fetchLatest();
		fetchVolume();
		computeTop();
	}

	/** Fast: just the live prices (margins + recommendations). */
	public void refreshLatest()
	{
		fetchLatest();
		computeTop();
	}

	/** Slow: hourly volume (changes slowly). */
	public void refreshVolume()
	{
		fetchVolume();
		computeTop();
	}

	private void fetchLatest()
	{
		JsonObject data = fetchData(LATEST);
		if (data == null)
		{
			return;
		}
		Map<Integer, int[]> m = new HashMap<>(data.size() * 2);
		for (Map.Entry<String, JsonElement> e : data.entrySet())
		{
			try
			{
				int id = Integer.parseInt(e.getKey());
				JsonObject o = e.getValue().getAsJsonObject();
				int low = o.has("low") && !o.get("low").isJsonNull() ? o.get("low").getAsInt() : 0;
				int high = o.has("high") && !o.get("high").isJsonNull() ? o.get("high").getAsInt() : 0;
				if (low > 0 || high > 0)
				{
					m.put(id, new int[]{low, high});
				}
			}
			catch (Exception ignored)
			{
			}
		}
		prices = m;
	}

	private void fetchVolume()
	{
		JsonObject data = fetchData(HOURLY);
		if (data == null)
		{
			return;
		}
		Map<Integer, Integer> m = new HashMap<>(data.size() * 2);
		for (Map.Entry<String, JsonElement> e : data.entrySet())
		{
			try
			{
				int id = Integer.parseInt(e.getKey());
				JsonObject o = e.getValue().getAsJsonObject();
				int hv = o.has("highPriceVolume") && !o.get("highPriceVolume").isJsonNull() ? o.get("highPriceVolume").getAsInt() : 0;
				int lv = o.has("lowPriceVolume") && !o.get("lowPriceVolume").isJsonNull() ? o.get("lowPriceVolume").getAsInt() : 0;
				m.put(id, hv + lv);
			}
			catch (Exception ignored)
			{
			}
		}
		volumes = m;
	}

	private JsonObject fetchData(String url)
	{
		try
		{
			Request req = new Request.Builder().url(url).header("User-Agent", UA).build();
			try (Response r = http.newCall(req).execute())
			{
				if (!r.isSuccessful() || r.body() == null)
				{
					return null;
				}
				JsonObject root = gson.fromJson(r.body().charStream(), JsonObject.class);
				return root != null && root.has("data") ? root.getAsJsonObject("data") : null;
			}
		}
		catch (Exception ex)
		{
			log.warn("OnlyFlips fetch failed: {}", url, ex);
			return null;
		}
	}

	/** Recompute the recommended flips using the current config filters. Cheap; safe to call on config change. */
	public void computeTop()
	{
		final Map<Integer, int[]> px = prices;
		final Map<Integer, Integer> vol = volumes;
		if (px.isEmpty())
		{
			return;
		}
		final long minProfit = config.minProfit();
		final long minVolume = config.minVolume();
		// Free accounts are limited to 3 recommendations; Pro unlocks the configured count
		final int count = account.isPro() ? Math.max(1, config.topCount()) : Math.min(3, Math.max(1, config.topCount()));

		List<int[]> out = new ArrayList<>();
		for (Map.Entry<Integer, int[]> e : px.entrySet())
		{
			final int id = e.getKey();
			final int low = e.getValue()[0], high = e.getValue()[1];
			if (low <= 0 || high <= 0)
			{
				continue;
			}
			final int v = vol.getOrDefault(id, 0);
			if (v < minVolume)
			{
				continue;
			}
			final long tax = OnlyFlipsPlugin.geTax(high, id);
			final long margin = high - low - tax;
			if (margin < minProfit)
			{
				continue;
			}
			out.add(new int[]{id, (int) margin, v});
		}
		out.sort(Comparator.comparingInt((int[] a) -> a[1]).reversed());
		topFlips = out.size() > count ? new ArrayList<>(out.subList(0, count)) : out;
	}

	/** @return [low, high] or null if unknown */
	public int[] get(int itemId)
	{
		return prices.get(itemId);
	}

	/** @return list of [itemId, margin, volume], best first */
	public List<int[]> getTopFlips()
	{
		return topFlips;
	}

	public boolean ready()
	{
		return !prices.isEmpty();
	}
}

package com.onlyflips;

import javax.inject.Singleton;

/**
 * Tracks this session's flipping performance for the session overlay.
 * Profit is approximated as (sell revenue - buy cost - tax) over the session.
 */
@Singleton
public class OnlyFlipsSession
{
	private long buyTotal;
	private long sellTotal;
	private long taxTotal;
	private int flips;
	private long startMs = System.currentTimeMillis();

	public synchronized void onBuy(long spent)
	{
		buyTotal += spent;
	}

	public synchronized void onSell(long spent, long tax)
	{
		sellTotal += spent;
		taxTotal += tax;
		flips++;
	}

	public synchronized void reset()
	{
		buyTotal = 0;
		sellTotal = 0;
		taxTotal = 0;
		flips = 0;
		startMs = System.currentTimeMillis();
	}

	public synchronized long profit()
	{
		return sellTotal - buyTotal - taxTotal;
	}

	public synchronized long taxPaid()
	{
		return taxTotal;
	}

	public synchronized int flips()
	{
		return flips;
	}

	public synchronized double roi()
	{
		return buyTotal > 0 ? (profit() * 100.0 / buyTotal) : 0.0;
	}

	public long elapsedMs()
	{
		return System.currentTimeMillis() - startMs;
	}

	public synchronized long hourlyProfit()
	{
		long ms = elapsedMs();
		if (ms < 1000)
		{
			return 0;
		}
		return Math.round(profit() * 3_600_000.0 / ms);
	}
}

package com.onlyflips;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Live "Total Profit" session box, like the classic flipping session tracker.
 */
public class OnlyFlipsSessionOverlay extends OverlayPanel
{
	static final String RESET = "Reset";

	private static final Color GOLD = new Color(0xFF, 0xCE, 0x4A);
	private static final Color GREEN = new Color(0x57, 0xE0, 0x8A);
	private static final Color RED = new Color(0xFF, 0x6F, 0x6F);
	private static final Color MUTED = new Color(0x9B, 0x93, 0xB5);

	private final OnlyFlipsSession session;
	private final OnlyFlipsConfig config;

	@Inject
	OnlyFlipsSessionOverlay(OnlyFlipsSession session, OnlyFlipsConfig config)
	{
		this.session = session;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(175, 0));
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, RESET, "OnlyFlips session"));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showSession())
		{
			return null;
		}
		final long profit = session.profit();
		final Color pc = profit >= 0 ? GREEN : RED;

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text("Total Profit").color(GOLD).build());
		panelComponent.getChildren().add(TitleComponent.builder().text(OnlyFlipsPlugin.shortGp(profit) + " gp").color(pc).build());

		add("ROI", String.format("%.2f%%", session.roi()), profit >= 0 ? GREEN : RED);
		add("Flips made", Integer.toString(session.flips()), MUTED);
		add("Tax paid", OnlyFlipsPlugin.shortGp(session.taxPaid()) + " gp", MUTED);
		add("Session time", fmtClock(session.elapsedMs()), MUTED);
		add("Hourly profit", OnlyFlipsPlugin.shortGp(session.hourlyProfit()) + " gp/hr", session.hourlyProfit() >= 0 ? GREEN : RED);

		return super.render(g);
	}

	private void add(String label, String value, Color valueColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(label)
			.leftColor(MUTED)
			.right(value)
			.rightColor(valueColor)
			.build());
	}

	private static String fmtClock(long ms)
	{
		long s = ms / 1000L;
		long h = s / 3600L;
		long m = (s % 3600L) / 60L;
		s = s % 60L;
		return String.format("%02d:%02d:%02d", h, m, s);
	}
}

