 */
public class OnlyFlipsSmartOverlay extends OverlayPanel
{
	private static final Color GOLD = new Color(0xFF, 0xCE, 0x4A);
	private static final Color GREEN = new Color(0x57, 0xE0, 0x8A);
	private static final Color PURPLE = new Color(0xA7, 0x8B, 0xFA);
	private static final Color MUTED = new Color(0x9B, 0x93, 0xB5);

	private final OnlyFlipsAccount account;
	private final OnlyFlipsConfig config;

	@Inject
	OnlyFlipsSmartOverlay(OnlyFlipsAccount account, OnlyFlipsConfig config)
	{
		this.account = account;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(190, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showSmartPicks())
		{
			return null;
		}
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text("Smart Picks").color(GOLD).build());

		if (!account.isPro())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("🔒 Pro feature").leftColor(PURPLE).build());
			panelComponent.getChildren().add(LineComponent.builder().left("Go Pro on OnlyFlips").leftColor(MUTED).build());
			return super.render(g);
		}

		final List<OnlyFlipsAccount.Pick> picks = account.picks();
		if (picks == null || picks.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Loading…").leftColor(MUTED).build());
			return super.render(g);
		}

		int rank = 1;
		for (OnlyFlipsAccount.Pick p : picks)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left((p.owned ? "★ " : "") + rank + ". " + p.name)
				.leftColor(p.owned ? GOLD : Color.WHITE)
				.right("+" + OnlyFlipsPlugin.shortGp(p.margin))
				.rightColor(GREEN)
				.build());
			rank++;
		}
		return super.render(g);
	}
}

package com.onlyflips;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A small movable box listing the best items to flip right now.
 */
public class OnlyFlipsTopOverlay extends OverlayPanel
{
	private static final Color GOLD = new Color(0xFF, 0xCE, 0x4A);
	private static final Color GREEN = new Color(0x57, 0xE0, 0x8A);
	private static final Color MUTED = new Color(0x9B, 0x93, 0xB5);

	private final OnlyFlipsPriceService prices;
	private final ItemManager itemManager;
	private final OnlyFlipsConfig config;

	@Inject
	OnlyFlipsTopOverlay(OnlyFlipsPriceService prices, ItemManager itemManager, OnlyFlipsConfig config)
	{
		this.prices = prices;
		this.itemManager = itemManager;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(180, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showTopFlips())
		{
			return null;
		}
		final List<int[]> top = prices.getTopFlips();
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text("Top Flips").color(GOLD).build());

		if (top == null || top.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(prices.ready() ? "None match filters" : "Loading…")
				.leftColor(MUTED)
				.build());
			return super.render(g);
		}

		int rank = 1;
		for (int[] f : top)
		{
			String name;
			try
			{
				name = itemManager.getItemComposition(f[0]).getName();
			}
			catch (Exception e)
			{
				name = "Item " + f[0];
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left(rank + ". " + name)
				.right("+" + OnlyFlipsPlugin.shortGp(f[1]))
				.rightColor(GREEN)
				.build());
			rank++;
		}
		return super.render(g);
	}
}

